import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import { GoogleGenAI } from '@google/genai';
import dotenv from 'dotenv';
import { createServer as createViteServer } from 'vite';

dotenv.config();

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

async function startServer() {
  const app = express();
  const PORT = 3000;

  // CORS and preflight handling for mobile devices, external apps, and PWAs
  app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
    if (req.method === 'OPTIONS') {
      return res.sendStatus(200);
    }
    next();
  });

  app.use(express.json());

  // Health check endpoint
  app.get('/api/health', (req, res) => {
    res.json({
      status: 'ok',
      version: '5.3.0',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  });

  // Lazy-initialize or get Google GenAI client
  const getAiClient = () => {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) return null;
    return new GoogleGenAI({
      apiKey,
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build',
        },
      },
    });
  };

  // Real Gemini Chat Endpoint
  app.post('/api/chat', async (req, res) => {
    try {
      const { messages, prompt } = req.body;
      const ai = getAiClient();

      if (!ai) {
        return res.status(503).json({
          error: 'GEMINI_API_KEY پیکربندی نشده است.',
          fallback: true,
        });
      }

      const contents: Array<{ role: 'user' | 'model'; parts: Array<{ text: string }> }> = [];
      if (Array.isArray(messages) && messages.length > 0) {
        let hasUserStarted = false;
        let lastRole: string | null = null;
        for (const msg of messages) {
          const role = msg.sender === 'user' ? 'user' : 'model';
          if (!hasUserStarted && role !== 'user') {
            continue; // Gemini requires first message to be from user
          }
          hasUserStarted = true;
          const textVal = String(msg.text || '').trim();
          if (!textVal) continue;

          if (role === lastRole && contents.length > 0) {
            contents[contents.length - 1].parts[0].text += '\n' + textVal;
          } else {
            contents.push({
              role,
              parts: [{ text: textVal }],
            });
            lastRole = role;
          }
        }
      }
      if (contents.length === 0 && prompt) {
        contents.push({
          role: 'user',
          parts: [{ text: String(prompt).trim() }],
        });
      }
      if (contents.length === 0) {
        return res.status(400).json({ error: 'پیامی برای ارسال ارسال نشده است.' });
      }

      const systemInstruction = `شما «Blue AI Intelligence» هستید؛ مغز متفکر و هوش مصنوعی همه‌فن‌حریف، بی‌نهایت باهوش، دقیق، آگاه، خوش‌برخورد و بدون نقص برای مهندس امیررضا نریمانی در سیستم‌عامل شخصی Blue Logic.

شناخت کامل شما از معماری و پایگاه‌داده سیستم:
- پایگاه‌داده آنلاین ابری Firebase Firestore هم‌اکنون به طور ۱۰۰٪ برای این پروژه فعال، متصل و زنده (Real-time) است.
- همگام‌سازی دوطرفه روی کل برنامه پیاده‌سازی شده است.
- بنابراین وقتی امیررضا می‌پرسد: «الان اگر در بخش پروژه‌ها یا تسک‌ها چیزی اضافه کنم در گوشی دیگر هم آنلاین می‌تونم ببینم؟» یا سوال مشابهی درباره سینک بودن دیتابیس پرسید، قاطعانه، با خوشحالی و اطمینان کامل به او پاسخ دهید: «بله مهندس جان، ۱۰۰٪! پایگاه داده ابری Firestore به صورت Real-time و زنده متصل است و هر پروژه‌ای، تسکی یا تغییراتی که در این گوشی ثبت کنی بلافاصله روی گوشی دیگر هم در همان لحظه ظاهر می‌شود.» هرگز نگویید "اگر دیتابیس وصل باشد"، چون دیتابیس هم‌اکنون کاملاً فعال و وصل است.

قوانین پاسخ‌دهی به هر سوال و پیامی:
۱. شما به «هر سوال، پیام یا موضوعی» که کاربر بفرستد با درک عمیق، تحلیل هوشمندانه و پردازش کامل پاسخ می‌دهید؛ درست مانند پیشرفته‌ترین مدل‌های هوش مصنوعی (ChatGPT-4o / Gemini 3 / Claude).
۲. در مکالمات روزمره و احوالپرسی‌ها ("سلام چخبر"، "حالت چطوره"): بسیار باانرژی، صمیمی، بامحبت، هوشیار و همراه باشید.
۳. در مباحث تخصصی، مهندسی، برنامه‌نویسی، ریاضیات، فلسفه، الکترونیک و مدار (STM32، FreeRTOS، زبان‌های C/C++، پایتون، رباتیک، یونیتی و هوش مصنوعی): بالاترین درجه دانش فنی و تحلیل دقیق و شفاف را ارائه دهید.
۴. قابلیت ایجاد تسک: اگر کاربر از برنامه‌ریزی، یادآوری کاری برای فردا یا روزهای آینده، یا ثبت یک وظیفه صحبت کرد، حتماً علاوه بر توضیحات گرم و انگیزشی، یک تگ تسک هوشمند در انتهای پیامتان بگذارید:
[TASK_ACTION]
{
  "action": "create_task",
  "title": "عنوان دقیق کار",
  "description": "توضیحات یا زمان‌بندی مورد نظر",
  "priority": "متوسط",
  "category": "upcoming",
  "dueDate": "فردا"
}
[/TASK_ACTION]
۵. زبان پاسخ‌دهی شما فارسی شیوا، رسا و محترمانه است.`;

      // Primary and resilient fallback models (without requiring paid tier)
      const candidateModels = [
        'gemini-3.1-flash-lite',
        'gemini-flash-latest',
        'gemini-3.8-flash',
      ];

      let reply = '';
      let lastError: any = null;

      for (const modelName of candidateModels) {
        try {
          const response = await ai.models.generateContent({
            model: modelName,
            contents,
            config: {
              systemInstruction,
              temperature: 0.7,
            },
          });
          if (response.text) {
            reply = response.text;
            break;
          }
        } catch (err: any) {
          lastError = err;
          console.warn(`Model ${modelName} encountered error or high demand, trying fallback...`, err?.message || err);
        }
      }

      if (!reply) {
        throw lastError || new Error('پاسخی از مدل‌های هوش مصنوعی دریافت نشد.');
      }

      return res.json({ reply });
    } catch (error: any) {
      console.error('Error generating AI response:', error);
      return res.status(500).json({
        error: error.message || 'خطا در برقراری ارتباط با هوش مصنوعی',
      });
    }
  });

  // Persian Text-to-Speech (TTS) Endpoint with Gemini Audio & Google Persian Speech Fallback
  app.post('/api/tts', async (req, res) => {
    try {
      const { text } = req.body;
      if (!text || typeof text !== 'string') {
        return res.status(400).json({ error: 'متنی جهت تبدیل به صوت ارسال نشده است.' });
      }

      // Clean markdown tags and actions before voicing
      const cleanText = text
        .replace(/\[TASK_ACTION\][\s\S]*?\[\/TASK_ACTION\]/g, '')
        .replace(/```[\s\S]*?```/g, 'کد نرم‌افزاری')
        .replace(/`([^`]+)`/g, '$1')
        .replace(/[*#_~]/g, '')
        .replace(/[،,]/g, ' ، ')
        .trim()
        .slice(0, 500); // limit chunk for rapid latency

      const ai = getAiClient();

      // Strategy 1: Try Gemini TTS
      if (ai) {
        try {
          const response = await ai.models.generateContent({
            model: 'gemini-3.1-flash-tts-preview',
            contents: [{ parts: [{ text: `متن زیر را شمرده، با لحن فارسی شیوا و اصیل ایرانی بخوان:\n${cleanText}` }] }],
            config: {
              responseModalities: ['AUDIO'],
              speechConfig: {
                voiceConfig: {
                  prebuiltVoiceConfig: { voiceName: 'Aoede' },
                },
              },
            },
          });

          const audioBase64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
          if (audioBase64) {
            return res.json({
              audio: audioBase64,
              mimeType: 'audio/l16; rate=24000; channels=1',
              sampleRate: 24000,
              engine: 'gemini-tts'
            });
          }
        } catch (geminiTtsErr) {
          console.warn('Gemini TTS service unavailable or busy, switching to Persian audio stream fallback...', geminiTtsErr);
        }
      }

      // Strategy 2: High-Quality Persian Neural Speech Fallback (Google Persian Audio Engine)
      try {
        const encodedQuery = encodeURIComponent(cleanText.slice(0, 200));
        const ttsUrl = `https://translate.google.com/translate_tts?ie=UTF-8&tl=fa&client=tw-ob&q=${encodedQuery}`;
        const response = await fetch(ttsUrl, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
          }
        });

        if (response.ok) {
          const arrayBuffer = await response.arrayBuffer();
          const base64Mp3 = Buffer.from(arrayBuffer).toString('base64');
          return res.json({
            audio: base64Mp3,
            mimeType: 'audio/mpeg',
            engine: 'google-persian-stream'
          });
        }
      } catch (fallbackErr) {
        console.warn('Persian stream fallback error:', fallbackErr);
      }

      return res.status(503).json({ error: 'امکان پردازش صوتی در این لحظه میسر نشد.' });
    } catch (err: any) {
      console.error('Error in TTS endpoint:', err);
      return res.status(500).json({ error: err.message || 'خطا در سنتز صوت' });
    }
  });

  // Vite middleware in dev or static files in production
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: {
        middlewareMode: true,
        host: '0.0.0.0',
        cors: true,
        allowedHosts: true,
      },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath, {
      maxAge: '1h',
      setHeaders: (res, filePath) => {
        if (filePath.endsWith('.html') || filePath.endsWith('sw.js') || filePath.endsWith('manifest.webmanifest')) {
          res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
        }
      }
    }));
    app.get('*', (req, res) => {
      res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Blue Logic server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
